41:  /// (never the session cwd) with the session exports stripped — the
42:  /// invocation shape the verifier uses.
43:  Future<ProcessResult> graderParityRun(String script) => Process.run(
44:    '/bin/bash',
45:    [script],
46:    workingDirectory: '/',
47:    environment: {
48:      for (final entry in Platform.environment.entries)
