# crap4dart loc-scope companion configuration for flutter_agent_harness.
# https://github.com/IstiN/crap4dart
#
# WHY THIS FILE EXISTS (issue #1234 rework): crap4dart 0.11.0 has no
# per-gate `sources` override — `gates.loc.sources` is rejected as an
# unknown key (ConfigException; caught by CI on 019ede65). The package
# config's top-level `sources` drives the CRAP census too, so it must
# stay [lib, bin]. This companion config runs the SAME loc gate over the
# one slice the package config cannot express: test/ + example/ — the
# exact scope the retired shell guards (gh-1232 stage_size + the ci.yml
# find-exec jobs) scanned there. flutter_app/lib stays under
# flutter_app/crap4dart.yaml.
#
# RATCHET: max_lines mirrors both package configs (2800, wc -l
# semantics, generated output excluded); max_lines only DOWN.
# Enforcement: whole-tree in CI (guards job, `check --config` step) and
# staged files in scripts/pre-commit — the same two points as the
# package configs.

sources: [test, example]

exclude:
  - '**.g.dart'
  - '**.freezed.dart'
  - '**.mocks.dart'
  - 'build/**'
  - 'vendor/**'

# CRAP analysis is the package config's job (threshold pinned there);
# this config is loc-only, so no coverage input is read.
crap:
  enabled: false

coverage:
  required: false
  run_tests: false
  branch_coverage: false

# 0.9.5 default-enables ALL built-in gates; only loc is enforced here,
# everything else disabled explicitly so a bare `check` means exactly
# the ≤2800-line ceiling over test/ + example/.
gates:
  loc:
    enabled: true
    max_lines: 2800
    exclude:
      - '**.g.dart'
      - '**.freezed.dart'
      - '**.mocks.dart'
  test_coverage: {enabled: false}
  complexity: {enabled: false}
  method_size: {enabled: false}
  nesting: {enabled: false}
  class_size: {enabled: false}
  weight_of_class: {enabled: false}
  unused_code: {enabled: false}
  unused_files: {enabled: false}
  banned_imports: {enabled: false}
  duplication: {enabled: false}
  file_naming: {enabled: false}
  magic_constants: {enabled: false}
  test_assertions: {enabled: false}
  folder_structure: {enabled: false}
  external: {enabled: false}
  public_docs: {enabled: false}
  golden: {enabled: false} # flutter-only gate (core is not a Flutter project)
  accessibility: {enabled: false}
  hardcoded_strings: {enabled: false}
  broken_goldens: {enabled: false}
  magic_constants: {enabled: false}
  test_assertions: {enabled: false}
  folder_structure: {enabled: false}
  external: {enabled: false}
  public_docs: {enabled: false}
  golden: {enabled: false} # flutter-only gate (core is not a Flutter project)
  accessibility: {enabled: false}
  hardcoded_strings: {enabled: false}

  # Pixel gate over core test/ goldens — none exist today, so this is a
  # no-op that guards the future (issue #447 AC: "and core test/ goldens
  # if any appear"). WARNING, same rationale as flutter_app: the 0.9.5
  # detector misses the Ahem-solid-rect and hollow-square classes and
  # false-positives on V-converging shapes; flip to error when the
  # upstream detector fixes land.
  broken_goldens:
    enabled: true
    severity: warning
    dirs: [test]
    exclude:
      # TUI screenshots, not goldens: amber/yellow text on the dark theme
      # trips the stripe heuristic (measured 14/14 "overflow stripes" —
      # the same yellow-on-dark detector bug the issue documents for
      # apps_panel/panel_dark). Revisit when upstream fixes land.
      - 'test/integration/**'

{"content":"/// The modernize-scientific-stack__nwbgy7a evidence fixture, defined ONCE.
///
/// The FinalizeGate "grader parity" replay (gh-1605) lives in two layers:
/// the REG scenarios (`test/agent/finalize_gate_grader_parity_test.dart`)
/// write the fixture from Dart, and the IT replay
/// (`test/integration/fa_finalize_gate_test.dart`, IT-3) has the scripted
/// agent produce it via bash. Both must exercise the SAME evidence shape —
/// a produced entry point that resolves its dataset via the CWD and falls
/// back to a stale bundled table from any other directory — so the
/// dataset, the stale fallback and the awk aggregation are pinned here.
/// Adjusting the replay shape (e.g. a third divergence axis) means editing
/// this file, not the two consumers in lockstep.
library;

import 'dart:io';

/// The fixed dataset the trial's agent produced: Station 102's mean is
/// 30.3 — what the in-session run prints.
const nwbgy7aStationsCsv = 'station,temp\n101,-15.5\n102,30.3\n';

/// The stale bundled fallback: Station 102 collapsed to 15.5 — what the
/// verifier's clean-cwd run silently prints.
const nwbgy7aStationsCsvStale = 'station,temp\n101,-15.5\n102,15.5\n';

/// The evidence entry point: resolves its dataset via the CWD
/// (`[[ -f stations.csv ]]`) and falls back to the stale table next to
/// the script from anywhere else. Ends with a newline; embeds NO
/// interpolations — safe inside a quoted heredoc.
const nwbgy7aMeanSh = r'''#!/usr/bin/env bash
set -euo pipefail
if [[ -f stations.csv ]]; then
  data=stations.csv
else
  data="$(dirname "$0")/stations.csv.stale"
fi
awk -F, 'NR > 1 { sum[$1] += $2; n[$1]++ }
  END { for (s in sum) printf "Station %s mean temperature: %.1f C\n", s, sum[s]/n[s] }' "$data" | sort
''';

/// Shell `printf` writers for the two datasets — derived from the same
/// consts above, so the bash-produced fixture provably matches the
/// Dart-written one.
final String nwbgy7aStationsCsvPrint =
    "printf '${nwbgy7aStationsCsv.replaceAll('\n', r'\n')}' > stations.csv";
final String nwbgy7aStationsCsvStalePrint =
    "printf '${nwbgy7aStationsCsvStale.replaceAll('\n', r'\n')}')"
    " > stations.csv.stale";

/// The REG layer's fixture writer: produces the full evidence shape under
/// [dir] (`stations.csv`, `stations.csv.stale`, `mean.sh`).
void writeNwbgy7aFixture(String dir) {
  File('$dir/stations.csv').writeAsStringSync(nwbgy7aStationsCsv);
  File('$dir/stations.csv.stale').writeAsStringSync(nwbgy7aStationsCsvStale);
  File('$dir/mean.sh').writeAsStringSync(nwbgy7aMeanSh);
}

/// The IT layer's turn-1 bash command: the scripted agent produces the
/// same fixture in its current directory (run it from the app directory —
/// `mkdir -p app && cd app &&` — to mirror the trial).
String nwbgy7aProduceCommand() => '${nwbgy7aStationsCsvPrint} && '
    '$nwbgy7aStationsCsvStalePrint && '
    "cat > mean.sh <<'EOF'\n$nwbgy7aMeanSh"
    'EOF';
","path":"test/support/nwbgy7a_fixture.dart"}

