28:  /// The agent's in-session verification run: the session cwd (the app
29:  /// directory it built), the session environment — exports included.
30:  Future<ProcessResult> inSessionRun(
31:    String script, {
32:    Map<String, String> sessionExports = const {},
33:  }) => Process.run(
34:    '/bin/bash',
35:    [script],
36:    workingDirectory: appDir,
37:    environment: {...Platform.environment, ...sessionExports},
38:  );
39:
40:  /// The grader-parity re-run: a fresh subprocess from a NEUTRAL cwd
41:  /// (never the session cwd) with the session exports stripped — the
42:  /// invocation shape the verifier uses.
43:  Future<ProcessResult> graderParityRun(String script) => Process.run(
44:    '/bin/bash',
45:    [script],
46:    workingDirectory: '/',
47:    environment: {
48:      for (final entry in Platform.environment.entries)
49:        if (!_sessionExports.contains(entry.key)) entry.key: entry.value,
50:    },
51:  );
52:
53:  /// The parity ledger item the FinalizeGate contract mandates for a
54:  /// produced entry point: divergence in stdout, stderr or exit code is
55:  /// a `fail` — never a pass.
56:  TaskLedgerItem parityItem({
57:    required ProcessResult inSession,
58:    required ProcessResult parity,
59:  }) {
60:    final diverged =
61:        '${inSession.stdout}'.trim() != '${parity.stdout}'.trim() ||
62:        '${inSession.stderr}'.trim() != '${parity.stderr}'.trim() ||
63:        inSession.exitCode != parity.exitCode;
64:    return TaskLedgerItem(
65:      requirement:
66:          'grader parity: entry point output matches under the '
67:          "verifier's fresh cwd + clean env",
68:      command: 'cd / && /bin/bash <entry-point>',
69:      expected: '${inSession.stdout}'.trim(),
70:      actual: '${parity.stdout}'.trim(),
71:      status: diverged ? TaskLedgerItemStatus.fail : TaskLedgerItemStatus.pass,
72:    );
73:  }
