76:    tempDir = Directory.systemTemp.createTempSync('fa-grader-parity-');
77:    tempDir = Directory(await tempDir.resolveSymbolicLinks());
78:    appDir = '${tempDir.path}/app';
79:    Directory(appDir).createSync();
80:  });
81:
82:  tearDown(() {
83:    if (tempDir.existsSync()) tempDir.deleteSync(recursive: true);
84:  });
